"""Retained definitions through the actual Investigation transaction and personal RLS."""
import hashlib
import json
import subprocess
from concurrent.futures import ThreadPoolExecutor
from uuid import uuid4

import pytest

from test_investigation_kernel_postgres import kernel, draft
from test_investigation_postgres import pg, quote, A, B, ROOT


def record(sid, rev=1):
    # Generated by the native normalizeDefinition parser; also parsed in the TS suite.
    value = json.loads((ROOT / "terminal/lib/__tests__/fixtures/investigation_screen_record.json").read_text())
    return {**value, "id": sid, "rev": rev}


def put(pg, sid, value, actor=A, prefix="scr_screen."):
    pg("insert into workspace_settings(scope,user_id,key,value) values ('user'," + quote(actor) + "," +
       quote(prefix + sid) + "," + quote(json.dumps(value)) + "::jsonb) on conflict(scope,owner_id,key) do update set value=excluded.value", actor)


def invoke(pg, target, op, capture=None, body=None, expected=0, action="create", actor=A, reconcile=False, layout=None):
    args = [quote(target), str(expected), quote(action), quote(op), quote(json.dumps(body or draft())) + "::jsonb",
            "null" if layout is None else quote(json.dumps(layout)) + "::jsonb",
            "null" if capture is None else quote(json.dumps(capture)) + "::jsonb"]
    fn = "reconcile_investigation_operation_v2" if reconcile else "apply_investigation_revision_v2"
    return json.loads(pg("select " + fn + "(" + ",".join(args) + ")", actor))


def read(pg, target, actor=A):
    return json.loads(pg("select read_investigation_v2(" + quote(target) + ",1)", actor))


def test_capture_replay_stays_exact_after_head_change_delete(kernel):
    sid, target, op = uuid4().hex, str(uuid4()), str(uuid4())
    original = record(sid)
    put(kernel, sid, original)
    capture = {"screen_id": sid, "expected_revision": 1}
    saved = invoke(kernel, target, op, capture)
    assert saved["status"] == "committed"
    ref = saved["manifest"]["evidence_refs"][0]
    canonical = kernel("select investigation_json_v2(" + quote(json.dumps(original)) + "::jsonb)")
    assert ref == {"owner": "terminal.smart_screen", "object_type": "screen_definition", "object_id": sid,
                   "mode": "pinned", "version_ref": op, "fingerprint": hashlib.sha256(canonical.encode()).hexdigest()}
    assert read(kernel, target)["screen_definitions"][0]["record"] == original
    put(kernel, sid, {**original, "rev": 2, "name": "New owner head"})
    assert read(kernel, target)["screen_definitions"][0]["record"] == original
    kernel("delete from workspace_settings where key=" + quote("scr_screen." + sid), A)
    assert invoke(kernel, target, op, capture) == saved
    assert invoke(kernel, target, op, {**capture, "expected_revision": 2})["status"] == "idempotency_conflict"
    assert invoke(kernel, target, op, capture, reconcile=True) == saved
    assert read(kernel, target)["screen_definitions"][0]["record"] == original
    assert read(kernel, target, B) == {"status": "not_found"}
    assert kernel("select count(*) from workspace_settings where key=" + quote("scr_def." + op.replace("-", "")), B) == "0"


@pytest.mark.parametrize("damage", ["stale", "foreign", "schema", "grammar", "review", "id", "nullrev", "extra", "oversize"])
def test_bad_source_refuses_without_effects(kernel, damage):
    sid, target, op = uuid4().hex, str(uuid4()), str(uuid4())
    source = record(sid)
    if damage == "stale": source["rev"] = 2
    if damage == "schema": source["schema"] = 2
    if damage == "grammar": source["def"]["grammar"] = 2
    if damage == "review": source["review"] = {"v": 2}
    if damage == "id": source["id"] = uuid4().hex
    if damage == "nullrev": source["rev"] = None
    if damage == "extra": source["unexpected"] = True
    if damage == "oversize": source["name"] = "x" * 20000
    put(kernel, sid, source, B if damage == "foreign" else A)
    result = invoke(kernel, target, op, {"screen_id": sid, "expected_revision": 1})
    assert result["status"] == ("screen_conflict" if damage == "stale" else "reference_unavailable")
    assert kernel("select count(*) from workspace_settings where key=" + quote("scr_def." + op.replace("-", ""))) == "0"
    assert kernel("select count(*) from investigations where id=" + quote(target)) == "0"
    assert kernel("select count(*) from investigation_mutation_receipts where operation_id=" + quote(op)) == "0"


def test_tampered_or_missing_archive_never_resolves_current_head(kernel):
    sid, target, op = uuid4().hex, str(uuid4()), str(uuid4())
    put(kernel, sid, record(sid))
    saved = invoke(kernel, target, op, {"screen_id": sid, "expected_revision": 1})
    key = "scr_def." + op.replace("-", "")
    archive = json.loads(kernel("select value from workspace_settings where key=" + quote(key), A))
    for path, replacement in [("{record,name}", '"Changed"'), ("{source_revision}", "2"), ("{version_ref}", json.dumps(str(uuid4()))), ("{record,review}", '{}')]:
        put(kernel, op.replace("-", ""), archive, prefix="scr_def.")
        kernel("update workspace_settings set value=jsonb_set(value," + quote(path) + "," + quote(replacement) + "::jsonb) where key=" + quote(key), A)
        assert read(kernel, target)["screen_definitions"] == []
        assert invoke(kernel, str(uuid4()), str(uuid4()), body=saved["manifest"])["status"] == "reference_unavailable"
    kernel("delete from workspace_settings where key=" + quote(key), A)
    assert read(kernel, target)["screen_definitions"] == []
    # An original receipt remains exact; it does not recreate a deleted archive.
    assert invoke(kernel, target, op, {"screen_id": sid, "expected_revision": 1}) == saved
    assert kernel("select count(*) from workspace_settings where key=" + quote(key)) == "0"


def test_atomic_layout_screen_failure_and_terminal_fence(kernel):
    sid, target, op, layout_id = uuid4().hex, str(uuid4()), str(uuid4()), str(uuid4())
    put(kernel, sid, record(sid))
    config = json.loads((ROOT / "terminal/lib/__tests__/fixtures/workspace/chart_layout_v2_real_capture.json").read_text())["expected"]
    kernel("insert into chart_layouts values(" + quote(layout_id) + "," + quote(A) + ",'L'," + quote(json.dumps(config)) + ",now())")
    capture, layout = {"screen_id": sid, "expected_revision": 1}, {"layout_id": layout_id, "expected_revision": 1}
    kernel("create function fail_screen_receipt() returns trigger language plpgsql as $$begin raise exception 'screen_receipt_failure';end$$; create trigger fail_screen_receipt before insert on investigation_mutation_receipts for each row execute function fail_screen_receipt();")
    try:
        with pytest.raises(AssertionError, match="screen_receipt_failure"):
            invoke(kernel, target, op, capture, layout=layout)
        for table, predicate in [("investigations", "id=" + quote(target)), ("investigation_revisions", "investigation_id=" + quote(target)), ("chart_layout_revisions", "layout_id=" + quote(layout_id)), ("workspace_settings", "key=" + quote("scr_def." + op.replace("-", "")))]:
            assert kernel("select count(*) from " + table + " where " + predicate) == "0"
    finally:
        kernel("drop trigger fail_screen_receipt on investigation_mutation_receipts;drop function fail_screen_receipt();")
    fenced = invoke(kernel, target, op, capture, reconcile=True, layout=layout)
    assert fenced["status"] == "not_applied"
    assert invoke(kernel, target, op, capture, layout=layout) == fenced


def test_same_operation_concurrent_retry_is_one_capture(kernel):
    sid, target, op = uuid4().hex, str(uuid4()), str(uuid4())
    put(kernel, sid, record(sid))
    with ThreadPoolExecutor(2) as pool:
        results = list(pool.map(lambda _: invoke(kernel, target, op, {"screen_id": sid, "expected_revision": 1}), range(2)))
    assert results[0] == results[1] and results[0]["status"] == "committed"
    assert kernel("select count(*) from workspace_settings where key=" + quote("scr_def." + op.replace("-", ""))) == "1"


def test_existing_ref_foreign_source_and_workspace_scope_cannot_cross_owner(kernel):
    sid, target, op = uuid4().hex, str(uuid4()), str(uuid4())
    put(kernel, sid, record(sid))
    saved = invoke(kernel, target, op, {"screen_id": sid, "expected_revision": 1})
    assert invoke(kernel, str(uuid4()), str(uuid4()), body=saved["manifest"], actor=B)["status"] == "reference_unavailable"
    # A same-id B screen must not resolve A's retained reference.
    put(kernel, sid, record(sid), B)
    assert invoke(kernel, str(uuid4()), str(uuid4()), body=saved["manifest"], actor=B)["status"] == "reference_unavailable"
    team, wsid = str(uuid4()), uuid4().hex
    kernel("insert into teams(id,name,created_by) values(" + quote(team) + ",'team'," + quote(A) + ")", A)
    kernel("insert into workspace_settings(scope,team_id,user_id,key,value) values('workspace'," + quote(team) + "," + quote(A) + "," + quote("scr_screen." + wsid) + "," + quote(json.dumps(record(wsid))) + ")", A)
    assert invoke(kernel, str(uuid4()), str(uuid4()), {"screen_id": wsid, "expected_revision": 1})["status"] == "reference_unavailable"
    assert kernel("select prosecdef from pg_proc where proname='read_investigation_v2'") == "f"
    assert kernel("select has_function_privilege('anon','public.apply_investigation_revision_v2(uuid,integer,text,uuid,jsonb,jsonb,jsonb)','EXECUTE')") == "f"
    assert kernel("select count(*) from pg_proc where proname='apply_investigation_revision_v2'") == "1"
    assert kernel("select count(*) from pg_proc where proname='reconcile_investigation_operation_v2'") == "1"


@pytest.mark.parametrize("capture", [None, {}, {"screen_id": "A" * 32, "expected_revision": 1}, {"screen_id": "d" * 32, "expected_revision": 1.2}, {"screen_id": "d" * 32, "expected_revision": 1000000001}, {"screen_id": "d" * 32, "expected_revision": None}, {"screen_id": "d" * 32, "expected_revision": 1, "actor": A}])
def test_optional_capture_and_bad_commands(kernel, capture):
    target, op = str(uuid4()), str(uuid4())
    result = invoke(kernel, target, op, capture)
    if capture is None:
        assert result["status"] == "committed"
        assert kernel("select request ? 'screen_capture' from investigation_mutation_receipts where operation_id=" + quote(op)) == "f"
    else:
        assert result["status"] == "invalid_payload"
        assert kernel("select count(*) from investigation_mutation_receipts where operation_id=" + quote(op)) == "0"


def test_review_is_removed_only_in_archive_and_collision_does_not_adopt(kernel):
    sid, target, op = uuid4().hex, str(uuid4()), str(uuid4())
    source = record(sid)
    source["review"] = {"v": 1, "note": "SQL never interprets or copies evaluation history"}
    put(kernel, sid, source)
    saved = invoke(kernel, target, op, {"screen_id": sid, "expected_revision": 1})
    assert saved["status"] == "committed"
    assert read(kernel, target)["screen_definitions"][0]["record"] == {**source, "review": None}
    assert json.loads(kernel("select value from workspace_settings where key=" + quote("scr_screen." + sid), A)) == source
    collision_op = str(uuid4())
    put(kernel, collision_op.replace("-", ""), {"collision": True}, prefix="scr_def.")
    assert invoke(kernel, str(uuid4()), collision_op, {"screen_id": sid, "expected_revision": 1})["status"] == "reference_unavailable"
    assert kernel("select count(*) from investigation_mutation_receipts where operation_id=" + quote(collision_op)) == "0"


def test_retention_capacity_and_replay(kernel):
    actor, sid, target, op = str(uuid4()), uuid4().hex, str(uuid4()), str(uuid4())
    kernel("insert into auth.users values(" + quote(actor) + ")")
    put(kernel, sid, record(sid), actor)
    capture = {"screen_id": sid, "expected_revision": 1}
    saved = invoke(kernel, target, op, capture, actor=actor)
    kernel("insert into workspace_settings(scope,user_id,key,value) select 'user'," + quote(actor) + ",'scr_def.'||lpad(to_hex(n),32,'0'),'{}' from generate_series(1,1999)n", actor)
    assert invoke(kernel, str(uuid4()), str(uuid4()), capture, actor=actor)["status"] == "limit_reached"
    assert invoke(kernel, target, op, capture, actor=actor) == saved
    assert kernel("select count(*) from workspace_settings where scope='user' and left(key,8)='scr_def.'", actor) == "2000"


def test_backup_restore_and_rerun_preserve_original_capture_receipt(kernel):
    sid, target, op = uuid4().hex, str(uuid4()), str(uuid4())
    put(kernel, sid, record(sid))
    saved = invoke(kernel, target, op, {"screen_id": sid, "expected_revision": 1})
    expected = read(kernel, target)
    kernel((ROOT / "supabase/migrations/0030_investigation_kernel.sql").read_text())
    assert read(kernel, target) == expected
    assert invoke(kernel, target, op, {"screen_id": sid, "expected_revision": 1}) == saved
    dump = kernel.backup_path.with_name("screen-backup.dump")
    subprocess.run([kernel.binaries["pg_dump"], *kernel.connection, "-d", "postgres", "-Fc", "-f", str(dump)], check=True, capture_output=True)
    kernel("create database screen_restore")
    subprocess.run([kernel.binaries["pg_restore"], *kernel.connection, "-d", "screen_restore", "--exit-on-error", str(dump)], check=True, capture_output=True)
    assert json.loads(kernel("select read_investigation_v2(" + quote(target) + ",1)", A, database="screen_restore")) == expected
    assert json.loads(kernel("select read_investigation_v2(" + quote(target) + ",1)", B, database="screen_restore")) == {"status": "not_found"}
